import {MOVES,SPECIES,ELEMENTS} from './data.js';
import {moveLearnset} from './moves.js';
import {abilityFor,basicRecovery} from './abilities.js';
export const moveDescription=(mon,id)=>id==='tackle'?`基础攻击，回复 ${basicRecovery(mon)} 点能量。`:MOVES[id].desc;
export function moveBookMarkup(mon,draft,slot,mode,changed){
 const species=SPECIES[mon.species],ability=abilityFor(mon),learnset=moveLearnset(mon),slots=Math.min(4,learnset.filter(m=>m.level<=mon.level).length);
 return `<div class="move-book-intro"><canvas width="192" height="192" data-species="${mon.species}" aria-hidden="true"></canvas><div><small>Lv.${mon.level} · ${species.name}</small><h3>把熟悉的招式，带上下一段旅程</h3><p>先选择一个技能位置，再挑选已经学会的招式。可以互换顺序；保存后生效。12 级可学会缔约辅助，22、38 级开放家族进阶战技。</p><span class="move-ability">${ability.icon} ${ability.name} · ${ability.desc}</span></div></div><div class="move-book-heading"><span>对战携带 · ${draft.length} / 4</span><small>${mode==='auto'?'自动搭配 · 随成长更新':'手动搭配 · 保留你的选择'}</small></div><div class="move-slots" role="group" aria-label="选择要调整的技能位置">${Array.from({length:4},(_,i)=>{const move=MOVES[draft[i]],color=ELEMENTS[move?.element]?.color||'#c9c5ae';return `<button data-move-slot="${i}" class="${i===slot?'selected':''}" ${i<slots?'':'disabled'} aria-pressed="${i===slot}" aria-label="技能位置 ${i+1}，${move?.name||(i<slots?'可以选择':'尚未开放')}" style="--move-color:${color}"><small>${String(i+1).padStart(2,'0')}</small><strong>${move?.name||(i<slots?'选择一招':'等待成长')}</strong><span>${move?`能量 ${move.cost}`:i<slots?'从技能记忆中选择':`Lv.${i===2?9:12} 开放`}</span></button>`;}).join('')}</div><div class="move-book-heading"><span>技能记忆</span><small>正在调整第 ${slot+1} 个位置</small></div><div class="move-library">${learnset.map(({id,level,tier})=>{const move=MOVES[id],at=draft.indexOf(id),locked=mon.level<level,color=ELEMENTS[move.element]?.color||'#c7c9b5',label=locked?`Lv.${level} 领悟`:at===slot?'当前招式':at>=0?`与第 ${at+1} 招互换`:`放入第 ${slot+1} 招`;return `<article class="move-memory ${locked?'locked':''}" style="--move-color:${color}"><div class="move-memory-top"><span>${ELEMENTS[move.element]?.name||'通用'}</span><small>${locked?'尚未学会':at>=0?'已携带 · 第 '+(at+1)+' 招':'可重新携带'}</small></div><h3>${move.name}${tier==='advanced'?`<small class="technique-label">${move.role}</small>`:''}</h3><p>${moveDescription(mon,id)}</p><div class="move-memory-meta"><span>${move.power?'威力 '+move.power:'辅助技能'}</span><span>能量 ${move.cost}</span><span>${level===1?'初始掌握':'Lv.'+level+' 领悟'}</span></div><button class="secondary" data-learned-move="${id}" ${locked||at===slot?'disabled':''} aria-label="${move.name}，${label}">${label}</button></article>`;}).join('')}</div><div class="move-book-footer"><p>手动搭配保留已选技能；未满四招时，基础招式会补入空位。自动搭配随成长更新四招基础组合，进阶战技需主动放入位置。</p><div class="card-actions"><button class="primary" id="save-loadout" ${changed?'':'disabled'}>保存搭配 →</button><button class="secondary" id="auto-loadout">恢复自动搭配</button><button class="text-button" id="cancel-loadout">返回伙伴资料</button></div></div>`;
}
